 accessibilityLabel="Back to courses"
 >
 <Text style={styles.backButtonText}>
 Back to courses
 </Text>
 </Pressable>
 </View>
 </View>
 </View>
 );
 }

if (!courseData) {
  return (
  <View style={[styles.container, { backgroundColor: colors.surface }]}>
  <View
  style={[
    styles.header,
    { backgroundColor: colors.surface },
  ]}
