 <Text style={[styles.heroTitle, { color: colors.onSurface }]}>
 {nextExercise.title}
 </Text>
 <View style={styles.heroDescriptionRow}>
 <View
 style={[
 styles.heroAccent,
 { backgroundColor: derivedColors.primary },
 ]}
 />
 <Text
 style={[
 styles.heroDescription,
 { color: colors.textSecondary },
